function brightestSpot(lamps: number[][]): number {
  let best = -1, at = 0;
  for (const [p, d] of lamps) {
    const x = p - d;
    let lit = 0;
    for (const [q, e] of lamps) if (q - e <= x && x <= q + e) lit++;
    if (lit > best || (lit === best && x < at)) { best = lit; at = x; }
  }
  return at;
}

