function brightestSpot(lamps: number[][]): number {
  const delta = new Map<number, number>();
  for (const [p, d] of lamps) {
    delta.set(p - d, (delta.get(p - d) ?? 0) + 1);
    delta.set(p + d + 1, (delta.get(p + d + 1) ?? 0) - 1);
  }
  const points = [...delta.keys()].sort((a, b) => a - b);
  let cur = 0, best = -1, at = 0;
  for (const x of points) {
    cur += delta.get(x)!;
    if (cur > best) { best = cur; at = x; }
  }
  return at;
}

